@model Umbraco.Bench.Umbraco.Models.Blocks.BlogPostListModel

<section>
    @if (!string.IsNullOrWhiteSpace(Model.Heading))
    {
        <h2 class="mb-8 text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
    }
    @if (Model.Posts.Count == 0)
    {
        <p class="text-slate-500">No posts yet.</p>
    }
    else
    {
        <div class="grid gap-8 md:grid-cols-2">
            @foreach (var post in Model.Posts)
            {
                <article class="group overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200 transition hover:shadow-xl">
                    <a href="@post.Url" class="block">
                        @if (post.ImageUrl is not null)
                        {
                            <img src="@post.ImageUrl" alt="" loading="lazy" class="aspect-[16/9] w-full object-cover transition duration-500 group-hover:scale-105" />
                        }
                        <div class="p-6">
                            <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm font-medium text-indigo-600">@post.PublishDate.ToString("d MMMM yyyy")</time>
                            <h3 class="mt-2 text-xl font-bold text-slate-900 group-hover:text-indigo-700">@post.Title</h3>
                            @if (!string.IsNullOrWhiteSpace(post.Teaser))
                            {
                                <p class="mt-3 text-slate-600">@post.Teaser</p>
                            }
                            <span class="mt-4 inline-block text-sm font-semibold text-indigo-600">Read post &rarr;</span>
                        </div>
                    </a>
                </article>
            }
        </div>
    }
</section>

